// 昨日の日付（日本時間）を作ります。
// ★UTCのまま計算すると、朝9時前の注文が前日に入ってしまいます。
const jst = new Date(Date.now() + 9 * 60 * 60 * 1000);
jst.setUTCDate(jst.getUTCDate() - 1);
const date = jst.toISOString().slice(0, 10);

return [{
  json: {
    date,
    q: `created_at:>='${date}T00:00:00+09:00' created_at:<='${date}T23:59:59+09:00'`,
  },
}];

