={{ JSON.stringify({ query: "query Orders($q: String!) {
  orders(first: 250, query: $q, sortKey: CREATED_AT) {
    pageInfo { hasNextPage }
    nodes {
      id name createdAt cancelledAt test taxesIncluded
      lineItems(first: 100) {
        pageInfo { hasNextPage }
        nodes {
          sku title quantity
          discountedTotalSet { shopMoney { amount } }
          taxLines { priceSet { shopMoney { amount } } }
        }
      }
    }
  }
}", variables: { q: $json.q } }) }}

