// ============================================================
//  Shopifyの注文を、商品ごとにまとめます。
//  ★計算はすべてここで行います。AIには渡しません。
//
//  ★SKU対応表はここに書きます。
//    新しい商品が増えたら、この SKU_MAP に1行足してください。
//    （config/sku-map.json と同じ内容にしておくこと）
// ============================================================
const SKU_MAP = {
  '101': 'スーツケースS', '105': 'スーツケースS', '106': 'スーツケースS',
  '107': 'スーツケースS', '108': 'スーツケースS', '109': 'スーツケースS',
  '110': 'スーツケースS', '111': 'スーツケースS',
  '201': 'スーツケースM', '206': 'スーツケースM', '210': 'スーツケースM',
  '211': 'スーツケースM', 'A207': 'スーツケースM', 'A208': 'スーツケースM',
  '301': 'スーツケースL', '306': 'スーツケースL', '307': 'スーツケースL',
  '308': 'スーツケースL', '310': 'スーツケースL',
  'ARUMI01': '多機能アルミ', 'ARUMI02': '多機能アルミ',
  'N_ARUMI01': 'クラシックアルミ', 'N_ARUMI02': 'クラシックアルミ',
  'OUTDOORSK002': 'アウトドア', 'BAG003': '圧縮バッグ',
  'F53K01': 'ハンディファン(首振り)', 'F53K01A': 'ハンディファン(首振り)',
  'F53K02': 'ハンディファン(首振り)',
  'X05001': 'ハンディファン(スケルトン)', 'X05002': 'ハンディファン(スケルトン)',
  'MSF002': 'ミニハンディファン', 'MSF003': 'ミニハンディファン',
  'MSF004': 'ミニハンディファン',
  'CF001': 'クリップファン', 'CF002': 'クリップファン',
  'MPD001': 'ツヤリスドライヤー', 'MPD002': 'ツヤリスドライヤー',
  'MPD003': 'ツヤリスドライヤー', 'MPD004': 'ツヤリスドライヤー',
  'ST-FC002': '電動洗顔ブラシ', 'ST-FC003': '電動洗顔ブラシ',
  'ST-FC004': '電動洗顔ブラシ', 'ST-FC006': '電動洗顔ブラシ',
};

const date = $('対象日を決める').first().json.date;
const res = $input.first().json;

if (res.errors && res.errors.length) {
  throw new Error('Shopifyが拒否しました: ' + res.errors.map(e => e.message).join(' / '));
}

const conn = res.data && res.data.orders;
const orders = (conn && conn.nodes) || [];
const warnings = [];
if (conn && conn.pageInfo && conn.pageInfo.hasNextPage) {
  warnings.push('注文が250件を超えました。超えたぶんは読めていません。');
}

const byProduct = new Map();
let cancelled = 0, testOrders = 0;
const orderIds = new Set();

for (const o of orders) {
  if (o.cancelledAt) { cancelled++; continue; }
  if (o.test) { testOrders++; continue; }
  if (o.lineItems && o.lineItems.pageInfo && o.lineItems.pageInfo.hasNextPage) {
    warnings.push('商品が100点を超える注文がありました: ' + o.name);
  }
  orderIds.add(o.name || o.id);

  const taxIncluded = o.taxesIncluded === true;
  for (const li of (o.lineItems && o.lineItems.nodes) || []) {
    const base = Number((li.discountedTotalSet && li.discountedTotalSet.shopMoney.amount) || 0);
    const tax = ((li.taxLines) || []).reduce(
      (s, t) => s + Number((t.priceSet && t.priceSet.shopMoney.amount) || 0), 0);
    const amount = taxIncluded ? base : base + tax;

    const sku = String(li.sku || '').trim();
    const mapped = SKU_MAP[sku.toUpperCase()];
    // ★対応表に無いものは断定しません。「未分類・要確認」として残します。
    const product = mapped || '未分類';
    const confidence = mapped ? '確定' : '要確認';

    const key = product + '__' + confidence;
    if (!byProduct.has(key)) {
      byProduct.set(key, { product, confidence, sku, title: li.title || '', qty: 0, amount: 0 });
    }
    const b = byProduct.get(key);
    b.qty += Number(li.quantity) || 0;
    b.amount += amount;
  }
}

const rows = [...byProduct.values()];
const total = rows.reduce((s, r) => s + r.amount, 0);
const qty = rows.reduce((s, r) => s + r.qty, 0);
const unmapped = rows.filter(r => r.confidence !== '確定');

return [{ json: {
  date, rows, total, qty,
  orders: orderIds.size,
  cancelled, testOrders, warnings,
  unmappedCount: unmapped.length,
} }];

// キントーンに入れる形にします。
// ★同じ日をもう一度入れても二重にならないよう、
//   「自社サイト」の明細だけを入れ替え、Amazon・楽天の明細は必ず残します。
const agg = $('商品ごとにまとめる').first().json;
const found = $input.first().json;
const existing = (found.records && found.records[0]) || null;

const kept = existing
  ? (existing.detail.value || []).filter(r => r.value.s_channel.value !== '自社サイト')
  : [];

const num = v => String(Math.round(Number(v) || 0));
const newRows = agg.rows.map(r => ({ value: {
  s_channel:    { value: '自社サイト' },
  s_product:    { value: r.product },
  s_sku:        { value: String(r.sku || '').slice(0, 64) },
  s_asin:       { value: '' },
  s_title:      { value: String(r.title || '').slice(0, 64) },
  s_qty:        { value: num(r.qty) },
  s_amount:     { value: num(r.amount) },
  s_orders:     { value: '' },
  s_confidence: { value: r.confidence },
} }));

const log = [
  '取込日時: ' + new Date().toLocaleString('ja-JP', { timeZone: 'Asia/Tokyo' }),
  '取得元: Shopify Admin API（n8n 自動連携）',
  '注文 ' + agg.orders + '件 / ' + agg.rows.length + '商品 / ' + agg.qty + '個',
  'キャンセル除外 ' + agg.cancelled + '件 / テスト注文除外 ' + agg.testOrders + '件',
].concat(agg.warnings.length ? ['⚠ ' + agg.warnings.join(' / ')] : []).join('\n');

return [{ json: {
  isUpdate: !!existing,
  recordId: existing ? existing.$id.value : null,
  hasRows: newRows.length > 0,
  summary: agg,
  record: {
    report_date: { value: agg.date },
    dedup_key:   { value: agg.date },
    source:      { value: 'API自動連携' },
    detail:      { value: kept.concat(newRows) },
    import_log:  { value: log },
  },
} }];

// Chatworkに送る文面を作ります（数字はすでに確定したものだけを並べます）
const d = $('キントーン用に組み立てる').first().json;
const s = d.summary;
const yen = n => '¥' + Math.round(n).toLocaleString('ja-JP');

const L = [];
L.push('[info][title]🛒 自社サイト（Shopify）売上 ' + s.date + '[/title]');
L.push('売上　' + yen(s.total) + '（' + s.qty + '個 / ' + s.orders + '注文）');
L.push('');
for (const r of s.rows.slice().sort((a, b) => b.amount - a.amount)) {
  L.push('　' + r.product + (r.confidence === '確定' ? '' : '（要確認）') +
         '　' + yen(r.amount) + '　' + r.qty + '個');
}
if (s.cancelled || s.testOrders) {
  L.push('');
  L.push('除外　キャンセル ' + s.cancelled + '件 / テスト注文 ' + s.testOrders + '件');
}
if (s.unmappedCount) {
  L.push('');
  L.push('⚠ 対応表に無いSKUが ' + s.unmappedCount + '件あります（未分類として計上）');
}
if (s.warnings.length) {
  L.push('');
  L.push('⚠ ' + s.warnings.join(' / '));
}
L.push('');
L.push('キントーン「売上明細（自動取込）」に' + (d.isUpdate ? '上書き' : '登録') + 'しました。');
L.push('[/info]');

return [{ json: { body: L.join('\n') } }];
